expect:(async () => { const A = (m, u, b) => fetch('/api' + u, { method: m, headers: { Authorization: 'Bearer ' + localStorage.getItem('erp_token'), 'Content-Type': 'application/json' }, body: b ? JSON.stringify(b) : undefined }).then(async (r) => { const t = await r.text(); return t ? JSON.parse(t) : null });
const cur = (await A('GET', '/currencies')).find((c) => c.active); const accs = await A('GET', '/accounts'); const ac = accs.find((a) => a.code === '1209');
for (const o of (await A('GET', '/payment-agencies')).filter((c) => c.name === 'QA회계1-외화PG')) await A('DELETE', '/payment-agencies/' + o.id);
const p = await A('POST', '/payment-agencies', { code: 'QA1PG', name: 'QA회계1-외화PG', accountId: ac.id, feeRate: 3, currencyId: cur.id });
const g = (await A('GET', '/payment-agencies')).find((c) => c.id === p.id);
const ok = p.currencyId === cur.id && p.foreignCurrency === true && g.currencyName === cur.name;
const u = await A('PUT', '/payment-agencies/' + p.id, { name: 'QA회계1-외화PG', accountId: ac.id, feeRate: 3, currencyId: null, active: true });
const ok2 = u.currencyId === null && u.foreignCurrency === false;
await A('DELETE', '/payment-agencies/' + p.id); return ok && ok2 })()
